نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
شکاف 13.2٪ بودجهٔ «شعبهٔ ۲۵» را تا ریشه باز کن. (شرق)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "store_pnl",
      "description": "فروش و بودجهٔ هفتگی هر شعبه",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "sales_m",
        "budget_m"
      ]
    },
    {
      "dataset": "foot_traffic",
      "description": "ترافیک و تراکنش روزانهٔ شعبه",
      "dimensions": [
        "branch",
        "day"
      ],
      "measures": [
        "visitors",
        "transactions"
      ]
    },
    {
      "dataset": "replenishment_log",
      "description": "تأخیر و پرشدن خطوط مکمل از مرکز توزیع",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "delay_days",
        "lines_filled_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "conversion_rate",
      "description": "نرخ تبدیل ترافیک به خرید",
      "formula": "تراکنش تقسیم بر بازدیدکننده",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "sales_per_sqm",
      "description": "فروش هر مترمربع",
      "formula": "فروش تقسیم بر مساحت فروشگاه",
      "unit": "هزار تومان",
      "dimensions": [
        "branch"
      ]
    }
  ],
  "business_context": [
    "۱۲۰ شعبه در پنج منطقه با سرپرست منطقه‌ای",
    "دوربین شمارش ترافیک در ورودی همهٔ شعب",
    "هدف‌گذاری فروش هفتگی برای هر شعبه"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "store_pnl",
    "filters": {
      "branch": "شعبهٔ ۲۵",
      "period": "this_month"
    }
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "foot_traffic",
    "filters": {
      "branch": "شعبهٔ ۲۵",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

