    "prev": 23.0,
    "curr": 19.3
  },
  "basket_avg_k_toman": 339,
  "lost_sales_m_est": 375
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "replenishment_log",
